    cumSpi: { name: 'Cumulative SPI (YTD)', what: 'Schedule efficiency since the start of the year.', calc: 'Σ EV ÷ Σ PV, year to date.', notes: 'Escalation rule: SPI < 0.90 → revise baseline and notify the client formally.' },
    cumCpi: { name: 'Cumulative CPI (YTD)', what: 'Cost efficiency since the start of the year.', calc: 'Σ EV ÷ Σ AC, year to date.', notes: 'Escalation rule: CPI < 0.95 → escalate; < 0.90 → cost recovery review.' },
    gateLag: { name: 'Approval Gate Lag', what: 'How long the contractor waits for client authorisations.', calc: 'Average hours from submission to authorisation, gates authorised in the month.', notes: 'Escalate anything pending beyond 48 h. Authorisation delays hidden here are the evidence for schedule and variation claims.' },
    verbalOpen: { name: 'Unconfirmed Verbal Instructions', what: 'Verbal instructions not yet confirmed in writing.', calc: 'Verbal instructions given on or before the evaluation date and not confirmed in writing by then.', notes: 'Target zero: an instruction that is not in writing is a scope and liability risk for the contractor.' },
    variationRecovery: { name: 'Variation Recovery', what: 'How much of the claimed variation value is approved.', calc: 'Value approved ÷ value claimed, variations decided year to date.', notes: 'Low recovery usually means weak evidence – check written confirmation and gate records.' },
